//Thanks to iq for some help with artifacts

vec3 rotate2D(vec3 p, vec2 t){
    float stx = sin(t.x);
    float ctx = cos(t.x);
    float sty = sin(t.y);
    float cty = cos(t.y);
    mat3 xRotation;
    xRotation[0] = vec3(1, 0, 0);
    xRotation[1] = vec3(0, ctx, -stx);
    xRotation[2] = vec3(0, stx, ctx);

    mat3 yRotation;
    yRotation[0] = vec3(cty, 0, -sty);
    yRotation[1] = vec3(0, 1, 0);
    yRotation[2] = vec3(sty, 0, cty);
    return p*xRotation*yRotation;
}

//Dave_Hoskins' Hash Without Sine
float random3(vec3 p){
    p = fract(p*0.1031);
    p += dot(p, p.zyx + 31.32);
    return (fract((p.x + p.y)*p.z)*2.0) - 1.0;
}

float random2(vec2 p){
    p = fract(p*0.1031);
    p += dot(p, p.yx + 31.32);
    return (fract(p.x + p.y)*2.0) - 1.0;
}

float noise3(vec3 p){
    vec3 fc = floor(p);
    vec3 frc = fract(p);
    frc = frc*frc*(3.0 - 2.0*frc);

    float tlf = random3(fc + vec3(0, 1, 0));
    float trf = random3(fc + vec3(1, 1, 0));
    float blf = random3(fc + vec3(0, 0, 0));
    float brf = random3(fc + vec3(1, 0, 0));
    float tlb = random3(fc + vec3(0, 1, 1));
    float trb = random3(fc + vec3(1, 1, 1));
    float blb = random3(fc + vec3(0, 0, 1));
    float brb = random3(fc + vec3(1, 0, 1));

    float lerpTopFront = mix(tlf, trf, frc.x);
    float lerpBottomFront = mix(blf, brf, frc.x);

    float lerpTopBack = mix(tlb, trb, frc.x);
    float lerpBottomBack = mix(blb, brb, frc.x);

    float lerpFront = mix(lerpBottomFront, lerpTopFront, frc.y);
    float lerpBack = mix(lerpBottomBack, lerpTopBack, frc.y);

    return mix(lerpFront, lerpBack, frc.z);
}

float noise2(vec2 p){
    vec2 fc = floor(p);
    vec2 frc = fract(p);
    frc = frc*frc*(3.0 - 2.0*frc);

    float tlf = random2(fc + vec2(0, 1));
    float trf = random2(fc + vec2(1, 1));
    float blf = random2(fc + vec2(0, 0));
    float brf = random2(fc + vec2(1, 0));

    float lerpTopFront = mix(tlf, trf, frc.x);
    float lerpBottomFront = mix(blf, brf, frc.x);

    return mix(lerpBottomFront, lerpTopFront, frc.y);
}

float fbm(vec3 p){
    float f = 1.0;
    float r = radians(57.0);
    float h = 1.0;
    float n = noise2(p.xz*f)*h;
    for(int i = 0; i < 8; i++){
        f *= 2.0;
        r += radians(57.0);
        h /= 2.0;
        n += noise2(rotate2D(p, vec2(0, r)).xz*f)*h;
    }
    return n/1.0;
}

float yPlane(vec3 p){
    return p.y;
}

float scene(vec3 p){
    return min((yPlane(p - vec3(0, -1, 0)) - fbm(p*0.05)*5.0)*0.65, (yPlane(p - vec3(0, -2, 0)) - noise2(p.xz*20.0)*0.002));
}

float raymarch(vec3 o, vec3 d, int ms, float md, float eps, out bool hit){
    float t = 0.0;
    hit = false;
    for(int i = 0; i < ms && t < md && !hit; i++){
        float s = scene(o + d*t);
        t += s;
        if(abs(s) < eps*t*0.1){
            hit = true;
            return t;
        }
    }
    hit = false;
    return t;
}

vec3 getNormal(vec3 h){
    return normalize(vec3(
        scene(vec3(h.x + 0.01, h.yz)) - scene(vec3(h.x - 0.01, h.yz)),
        scene(vec3(h.x, h.y + 0.01, h.z)) - scene(vec3(h.x, h.y - 0.01, h.z)),
        scene(vec3(h.xy, h.z + 0.01)) - scene(vec3(h.xy, h.z - 0.01))
    ));
}

float getLighting(vec3 h, vec3 ldir, vec3 n){
    float c = dot(n, -ldir);
    float cr = c;
    float lt = 0.0;
    bool hit = false;
    vec3 so = h + n*0.01;
    for(int i = 0; i < 50 && lt <= 30.0 && !hit; i++){
        float s = scene(so - ldir*lt);
        lt += s;
        if(abs(s) <= lt*0.001 && lt >= 0.0){
            hit = true;
            c -= 0.6;
        }else{
            c = cr;
        }
        //return c;
    }
    return c;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec3 col = vec3(0);
    vec3 lDir = normalize(vec3(-10, -10, -10));
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
    vec3 o = vec3(0, 4, iTime*3.0);
    vec3 d = normalize(rotate2D(vec3(uv, 1), vec2(radians(15.0), iTime*0.1)));
    bool hit;
    float t = raymarch(o, d, 150, 120.0, 0.01, hit);
    if(!hit) t = 500.0;
    //t *= 0.9;
    vec3 n = getNormal(o + d*t);
    float ny = n.y - 0.1;
    float rd = 1.0 - d.y;
    col = mix(
        vec3(
            rd/5.0 + 0.2,
            rd/2.0 + 0.2,
            rd + 0.2
        ),
        vec3(1),
        clamp(fbm((o + d*t).xzy*0.01) + 0.2, 0.0, 1.0)
    );

    float c = clamp(getLighting(o + d*t, lDir, n), 0.0, 1.0);

    vec3 rfd = normalize(d - 2.0*n*dot(n, d));

    float spec = pow(clamp(dot(-lDir, rfd), 0.0, 1.0), 9.0);
    bool rhit;
    vec3 rfo = (o + d*t) + n*0.01;
    float rft = raymarch(rfo, rfd, 100, 100.0, 0.01, rhit);
    if(!rhit) rft = 500.0;
    float rdy = 1.0 - rfd.y;
    vec3 rfclouds = mix(
        vec3(
            rdy/5.0 + 0.2,
            rdy/2.0 + 0.2,
            rdy + 0.2
        ),
        vec3(1),
        clamp(fbm((rfo + rfd*rft).xzy*0.01) + 0.2, 0.0, 1.0)
    );
    vec3 rn = getNormal(rfo + rfd*rft);
    float rc = clamp(getLighting(rfo + rfd*rft, lDir, rn), 0.0, 1.0);
    vec3 matcol = (o.y + d.y*t) > -1.94 ? mix(vec3(0.2, 0.15, 0.1) + spec/8.0, vec3(0.2, 0.5, 0) + spec/8.0, smoothstep(0.6, 0.7, ny))*c : (rhit ? mix(vec3(0.2, 0.5, 1)*c, mix(vec3(0.2, 0.15, 0.1), vec3(0.1, 0.5, 0), smoothstep(0.6, 0.7, ny))*rc, 0.3)*c + spec : mix(vec3(0.2, 0.5, 1), rfclouds, 0.3)*c + spec);

    if(hit){
        col = vec3(
            mix(matcol.r, col.r, 1.0 - exp(-t*0.01)),
            mix(matcol.g, col.g, 1.0 - exp(-t*0.01)),
            mix(matcol.b, col.b, 1.0 - exp(-t*0.012))
        );
    }

    fragColor = vec4(pow(col, vec3(1.0/2.2)), 1);
}
